def apply_rule(rule, a, b):
    if rule == 'fep':
        return a * 3
    if rule == 'blicket':
        return a + b + a
    return b + a

def interpret(sentence):
    lex = {'dax': 'R', 'wif': 'G', 'lug': 'B', 'zup': 'Y'}
    def atom(tokens):
        x = lex[tokens[0]]
        for t in tokens[1:]:
            if t == 'fep':
                x = x * 3
        return x
    parts = [[]]
    for t in sentence.split(' '):
        if t == 'kiki':
            parts.append([])
        else:
            parts[-1].append(t)
    out = ''
    for part in parts:
        groups = [[]]
        for t in part:
            if t == 'blicket':
                groups.append([])
            else:
                groups[-1].append(t)
        res = atom(groups[0])
        for g in groups[1:]:
            res = res + atom(g) + res
        out = res + out
    return out

