import math
def loglik(probs):
    total = 0.0
    for p in probs:
        total = total + math.log(p)
    return round(total, 2)

def scan(command):
    names = {'walk': 'WALK', 'jump': 'JUMP', 'look': 'LOOK', 'run': 'RUN'}
    out = []
    for piece in command.split(' and '):
        words = piece.split(' ')
        act = [names[words[0]]]
        if len(words) > 1:
            if words[1] == 'twice':
                act = act * 2
            elif words[1] == 'thrice':
                act = act * 3
        out = out + act
    return out

